import{_ as d,o as a,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"سطح کا نظریہ اور درجہ بندی","description":"","frontmatter":{},"headers":[],"relativePath":"ur/80-位面理论与分类.md","filePath":"ur/80-位面理论与分类.md"}'),e={name:"ur/80-位面理论与分类.md"};function l(h,t,i,n,u,s){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="سطح-کا-نظریہ-اور-درجہ-بندی" tabindex="-1">سطح کا نظریہ اور درجہ بندی <a class="header-anchor" href="#سطح-کا-نظریہ-اور-درجہ-بندی" aria-label="Permalink to &quot;سطح کا نظریہ اور درجہ بندی&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>80</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>سطح کا نظریہ، سطح کی درجہ بندی، قانون کی رکاوٹ، سطح کے نقاط، ہینگ یوان ژو</td></tr></tbody></table><h2 id="_1-سطح-کی-بنیادی-تعریف" tabindex="-1">1. سطح کی بنیادی تعریف <a class="header-anchor" href="#_1-سطح-کی-بنیادی-تعریف" aria-label="Permalink to &quot;1. سطح کی بنیادی تعریف&quot;">​</a></h2><p>تمام جانوں کے اینکر اصل کائنات (ہینگ یوان ژو) کے فریم ورک کے تحت، &quot;سطح&quot; سے مراد ایک نسبتاً مستحکم قوانین کے مجموعے سے متعین، آزادانہ جگہ-وقت کے تسلسل والے وجود کا علاقہ ہے۔ سطح محض &quot;دوسری دنیا&quot; نہیں ہے، بلکہ مختلف پیرامیٹر وقفوں میں قانونی نیٹ ورک کی عکاسی ہے۔ ہر سطح کے اپنے منفرد طبعی مستقل، توانائی کی کثافت، وقت کے بہاؤ کی رفتار اور شعور کی سرگرمی ہوتی ہے، یہ پیرامیٹرز مل کر该 سطح کے &quot;قانون کے فنگر پرنٹ&quot; کی تشکیل کرتے ہیں۔</p><p>سطح کا وجود ہینگ یوان ژو کے قانونی نیٹ ورک کی یکسانیت سے پیدا ہوتا ہے۔ کائنات کے بنیادی قوانین کے چلنے کے عمل میں، توانائی کی تقسیم، شعور کی رکاوٹ اور تاریخی ارتقاء کے فرق کی وجہ سے، قدرتی طور پر بے شمار مختلف پیرامیٹر والے قانونی علاقے بنتے ہیں۔ ان علاقوں کو &quot;قانون کی رکاوٹ&quot; سے الگ کیا جاتا ہے، رکاوٹ کی شدت کا انحصار ملحقہ سطحوں کے درمیان قانونی پیرامیٹر کے فرق کی ڈگری پر ہوتا ہے — فرق جتنا زیادہ، رکاوٹ اتنی موٹی، گزرنے کی مشکل اتنی زیادہ۔</p><p>اینکر میکانزم سطح کے نظریے میں مرکزی پوزیشن رکھتا ہے۔ اینکر بنیادی طور پر قانونی نیٹ ورک میں ایک مستحکم نوڈ ہے، یہ نہ صرف اپنی سطح کے قانون کے استحکام کو برقرار رکھ سکتا ہے، بلکہ بین السطح کنکشن کے اینکرنگ بیس کے طور پر بھی کام کر سکتا ہے۔ بین السطح گزر، مواصلات اور آثار قدیمہ جیسے تمام تعاملات کو اینکر کو نقاط کے ماخذ کے طور پر لے کر پوزیشن اور انضمام کرنا ضروری ہے۔</p><h2 id="_2-سطح-کی-درجہ-بندی-کا-نظام" tabindex="-1">2. سطح کی درجہ بندی کا نظام <a class="header-anchor" href="#_2-سطح-کی-درجہ-بندی-کا-نظام" aria-label="Permalink to &quot;2. سطح کی درجہ بندی کا نظام&quot;">​</a></h2><p>ہینگ یوان ژو کے اندر کی سطحوں کو قانونی پیرامیٹر، توانائی کی سطح اور تہذیب کی ترقی کی ڈگری کے مطابق، درج ذیل پانچ اقسام میں تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>قسم</th><th>قانون کی خصوصیات</th><th>توانائی کی کثافت</th><th>عام تہذیب کی شکل</th><th>گزرنے کی مشکل</th></tr></thead><tbody><tr><td>مادہ بنیادی سطح</td><td>طبعی قوانین غالب، توانائی واضح نہیں</td><td>کم</td><td>ٹیکنالوجی تہذیب، ابتدائی سادھک تہذیب</td><td>کم</td></tr><tr><td>توانائی ظاہر سطح</td><td>توانائی کے قوانین نیم واضح، سادھک نظام بالغ</td><td>درمیانی</td><td>درمیانہ-اعلیٰ سادھک تہذیب، جادو تہذیب</td><td>درمیانی</td></tr><tr><td>شعور غالب سطح</td><td>شعور کے قوانین واضح، مادہ کو خواہش سے شکل دی جا سکتی ہے</td><td>زیادہ</td><td>روحانی وجود تہذیب، شعور اجتماعی تہذیب</td><td>زیادہ</td></tr><tr><td>قانون ٹوٹا سطح</td><td>قوانین غیر مستحکم، بہت سارے قانونی دراڑیں موجود</td><td>انتہائی زیادہ اور بے ترتیب</td><td>جنگلی سطح، کھنڈرات سطح</td><td>انتہائی زیادہ</td></tr><tr><td>اصل قریبی سطح</td><td>کائنات کے بنیادی قوانین کے قریب، پیرامیٹر حد کے قریب</td><td>اصل کے قریب</td><td>سب سے بلند تہذیب، سطح کے محافظ</td><td>نظریاتی حد</td></tr></tbody></table><p>مندرجہ بالا پانچ اقسام کے علاوہ، کچھ خاص سطح کی اقسام بھی موجود ہیں، جن میں شامل ہیں: آئینہ سطح (کسی مخصوص سطح کے قانونی پیرامیٹر کے ساتھ انتہائی متوازی متوازی وجود)، درمیانی سطح (دو اہم سطحوں کی قانونی رکاوٹ کے درمیان واقع منتقلی کا علاقہ)، سوپ سطح (قانون کی سرگرمی انتہائی کم، تقریباً رکا ہوا قدیم سطح) اور نوزائیدہ سطح (قانونی نیٹ ورک حالیہ طور پر تشکیل پایا، پیرامیٹر ابھی مستحکم نہیں ہے ایسی نوجوان سطح)۔</p><h2 id="_3-سطح-کے-نقاط-اور-پوزیشن-کا-اصول" tabindex="-1">3. سطح کے نقاط اور پوزیشن کا اصول <a class="header-anchor" href="#_3-سطح-کے-نقاط-اور-پوزیشن-کا-اصول" aria-label="Permalink to &quot;3. سطح کے نقاط اور پوزیشن کا اصول&quot;">​</a></h2><p>بین السطح تعامل کی شرط ہے درست سطح کی پوزیشن۔ ہینگ یوان ژو نے اینکر کو بیس کے طور پر &quot;چار جہتی سطح کے نقاط کا نظام&quot; قائم کیا ہے، ہر سطح کو چار پیرامیٹرز سے منفرد طور پر طے کیا جاتا ہے:</p><ol><li><strong>قانون کے فنگر پرنٹ کوڈ</strong>:该 سطح کے بنیادی قانونی پیرامیٹر سے ہیش آپریشن کے ذریعے پیدا ہونے والا منفرد شناخت کنندہ، لمبائی 128 بٹ</li><li><strong>اینکر کا تعلق</strong>:该 سطح کا معلوم اینکر نیٹ ورک کے ساتھ کنکشن کی شدت، قدر کی حد 0 سے 1</li><li><strong>وقت کی رفتار کا تناسب</strong>:该 سطح کی وقت کی رفتار اور ہینگ یوان ژو کے معیاری وقت کا تناسب، عام حد 0.1 سے 10</li><li><strong>جگہ کی جہتوں کی تعداد</strong>:该 سطح کی قابل ادراک جگہ کی جہتوں کی تعداد، عام طور پر 3 سے 11 جہت</li></ol><p>سطح کے نقاط حاصل کرنے کے طریقوں میں شامل ہیں: اینکر نیٹ ورک خودکار دریافت، بین السطح مواصلاتی سگنل کی بازیافت، آثار قدیمہ کے کھنڈرات میں نقاط کی باقیات اور سطح گزرنے والے کی دستی ریکارڈ۔ تمام تصدیق شدہ سطح کے نقاط &quot;ہینگ یوان ژو سطح کے نقاط کا مرکزی ذخیرہ&quot; میں درج ہیں، اینکر کونسل کے ماتحت سطح انتظامیہ بیورو کے ذریعے یکجا دیکھ بھال کی جاتی ہے۔</p><h2 id="_4-سطحوں-کے-درمیان-قدرتی-تعامل" tabindex="-1">4. سطحوں کے درمیان قدرتی تعامل <a class="header-anchor" href="#_4-سطحوں-کے-درمیان-قدرتی-تعامل" aria-label="Permalink to &quot;4. سطحوں کے درمیان قدرتی تعامل&quot;">​</a></h2><p>یہاں تک کہ فعال گزرنے کی کارروائی نہ ہونے پر بھی، سطحوں کے درمیان قدرتی تعامل کے مظاہر موجود ہیں۔ سب سے عام ہے &quot;قانون کا رساو&quot; — ملحقہ سطحوں کے درمیان رکاوٹ کے مقامی کمزور ہونے کی وجہ سے، تھوڑی مقدار میں قانونی پیرامیٹر ایک دوسرے میں گھس جاتے ہیں، جس سے مقامی غیر معمولی مظاہر پیدا ہوتے ہیں۔ مثال کے طور پر مادہ بنیادی سطح میں کبھی کبھار دیکھے جانے والے &quot;مافوق الفطرت واقعات&quot; اکثر پڑوسی توانائی ظاہر سطح کے قانون کے رساو کی وجہ سے ہوتے ہیں۔</p><p>ایک اور قدرتی تعامل ہے &quot;سطح کی گونج&quot;۔ جب دو سطحوں کے قانون کے فنگر پرنٹ کوڈ میں اعلیٰ ڈگری کی مماثلت ہوتی ہے، تو ان کے درمیان متواتر قانونی گونج پیدا ہوتی ہے، جو اس ظاہر ہوتی ہے کہ دونوں سطحوں میں مخصوص مدت میں ملتے جلتے تاریخی واقعات، تہذیب کی سمت اور یہاں تک کہ کرداروں کی تقدیر بھی ملتی جلتی ہوتی ہے۔ سطح کی گونج سطح آثار قدیمہ کی اہم تحقیق کا موضوع ہے، گونج کے نمونوں کے تجزیے کے ذریعے نامعلوم سطح کی تہذیب کی حالت کا اندازہ لگایا جا سکتا ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سطح کا نظریہ بین السطح تعامل کے تمام مشقوں کا نظریاتی بنیاد ہے۔ سطح کی نوعیت، درجہ بندی اور پوزیشن کے اصول کو درست سمجھنا، گزرنے کے اصول، اخلاقی رہنما خطوط اور روک تھام کے میکانزم کو وضع کرنے کی شرط ہے۔ ہینگ یوان ژو کی سطح کی تحقیق ہمیشہ &quot;علم پہلے، تعامل احتیاط کے ساتھ&quot; کے اصول پر عمل کرتی ہے، تہذیب کی حدود کو وسعت دیتے ہوئے، اس بات کو یقینی بناتی ہے کہ کسی بھی سطح کی خود مختار ارتقاء میں ناقابل واپسی مداخلت نہ ہو۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>81-سطح گزرنے کے اصول</li><li>88-بین السطح اخلاقی رہنما خطوط</li><li>28-بین السطح اینکر کنکشن</li></ul>',21)])])}const p=d(e,[["render",l]]);export{q as __pageData,p as default};
